# Tomar una muestra para que el gráfico no sea tan pesado


# Crear DataFrame indicando dónde hay valores faltantes (True = faltante)
df_null = df_cleaned.isnull()

# Añadir índice para saber la fila
df_null['row'] = df_null.index

# Convertir a formato "largo" para Altair: columnas: row, column, is_missing
df_melted = df_null.melt(id_vars='row', var_name='column', value_name='is_missing')

# Gráfico de heatmap donde rojo indica missing
chart = alt.Chart(df_melted).mark_rect().encode(
    alt.X('row:O', axis=alt.Axis(title='Fila', labels=False, ticks=False)),
    alt.Y('column:N', title='Columna'),
    alt.Color('is_missing:N', scale=alt.Scale(domain=[True, False], range=['red', 'white']), title='Valor faltante')
).properties(
    width=800,
    height=400,
    title='Mapa de Valores Faltantes'
)

chart
