## DESAROLLO DE HAC 
### PIPELINE  Y GRAFICO DE ESTE MODELO
### Y GUARDADO DE DATOS EN EL DATAFRAME 

::: {#86375392 .cell execution_count=21}
``` {.python .cell-code}
pipeline_hac = Pipeline([
    ('scaler', StandardScaler()),
    ('agglo', AgglomerativeClustering(n_clusters=3))
])

labels_hac = pipeline_hac.fit_predict(X_combined)
df_processed['cluster_hac'] = labels_hac

X_scaled = pipeline_hac.named_steps['scaler'].transform(X_combined)
linked = linkage(X_scaled, method='complete')

plt.figure(figsize=(15, 7))
dendrogram(linked, orientation='top', distance_sort='descending', show_leaf_counts=True, leaf_font_size=8)
plt.title("Dendrogram - Clustering Jerárquico (Método Complete)", fontsize=14)
plt.xlabel("Sample Index")
plt.ylabel("Distance")
plt.tight_layout()
plt.show()
